public static String replaceNonAlphanumericByUnderscores(String name){
  int length=name.length();
  StringBuilder sb=new StringBuilder(length);
  for (int i=0; i < length; ++i) {
    char c=name.charAt(i);
    if (('a' > c || c > 'z') && ('A' > c || c > 'Z') && ('0' > c || c > '9')) {
      sb.append('_');
    }
 else {
      sb.append(c);
    }
  }
  return sb.toString();
}
